#include <cstddef>
#include <cstdint>
#include <iostream>
#include <type_traits>
#include <vector>

constexpr std::size_t kCacheLine = 64;  // g++ 10.2 has no std::hardware_destructive_interference_size

// A trailing return type: the same function as std::size_t lines_in(std::size_t bytes).
auto lines_in(std::size_t bytes) -> std::size_t {
    return bytes / kCacheLine;
}

int main() {
    constexpr auto CacheLineSize = kCacheLine;
    constexpr auto EvictCacheLineSize = CacheLineSize * (2 << 12);
    constexpr auto Trials = 20'000;
    std::vector<uint8_t> CacheLineData(CacheLineSize), CacheLineEvictData(EvictCacheLineSize);
    std::vector<uint8_t> braced{CacheLineSize};

    std::cout << std::boolalpha;
    std::cout << "2 << 12 = " << (2 << 12) << ", 2 ^ 12 = " << (2 ^ 12) << '\n';
    std::cout << "EvictCacheLineSize = " << EvictCacheLineSize << " bytes, " << lines_in(EvictCacheLineSize)
              << " lines\n";
    std::cout << "a const size_t: " << std::is_same_v<decltype(EvictCacheLineSize), const std::size_t> << '\n';
    std::cout << "Trials = " << Trials << ", a const int: " << std::is_same_v<decltype(Trials), const int> << '\n';
    std::cout << "sizes: " << CacheLineData.size() << ", " << CacheLineEvictData.size() << ", " << braced.size()
              << '\n';
    std::cout << "braced[0] = " << static_cast<int>(braced[0]) << '\n';
    return 0;
}

