#include <chrono>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <vector>

using std::chrono::steady_clock;

constexpr std::size_t kCacheLine = 64;  // g++ 10.2 has no std::hardware_destructive_interference_size

auto MeasureFlood() -> void {
    constexpr auto CacheLineSize = kCacheLine;
    constexpr auto EvictCacheLineSize = CacheLineSize * (2 << 12);
    constexpr auto Trials = 200;
    std::vector<uint8_t> CacheLineData(CacheLineSize), CacheLineEvictData(EvictCacheLineSize, 1);
    volatile uint64_t sink = 0;
    auto floodTime = 0.0;
    for (std::size_t trials = 0; trials < Trials; trials++) {  // was: auto trials{0uz}; trials < Trials.size()
        auto floodStart = steady_clock::now();
        for (std::size_t i = 0; i < EvictCacheLineSize; i += CacheLineSize) {
            sink = sink + CacheLineEvictData[i];  // one byte from every line
        }
        auto floodEnd = steady_clock::now();
        floodTime += std::chrono::duration<double, std::micro>(floodEnd - floodStart).count();
    }
    std::cout << "lines per flood: " << EvictCacheLineSize / CacheLineSize << '\n';
    std::cout << "floods: " << Trials << '\n';
    std::cout << "lines touched: " << sink << '\n';
    std::cout << "time measured: " << std::boolalpha << (floodTime > 0) << '\n';
    // std::cout << floodTime / Trials << " us per flood\n";
}

int main() {
    MeasureFlood();
    return 0;
}

