#include <chrono>
#include <cstddef>
#include <iostream>
#include <type_traits>

using std::chrono::steady_clock;

// The hint an editor would draw for a variable of type T. decltype(x) gives x's type.
template <typename T>
const char* hint() {
    if (std::is_same_v<T, const unsigned long>) return ": const unsigned long";
    if (std::is_same_v<T, const int>) return ": const int";
    if (std::is_same_v<T, unsigned long>) return ": unsigned long";
    if (std::is_same_v<T, double>) return ": double";
    if (std::is_same_v<T, steady_clock::time_point>) return ": time_point";
    return ": some other type";
}

int main() {
    constexpr std::size_t kCacheLine = 64;  // where the snippet had std::hardware_destructive_interference_size
    constexpr auto CacheLineSize = kCacheLine;
    constexpr auto EvictCacheLineSize = CacheLineSize * (2 << 12);
    constexpr auto Trials = 20'000;
    auto floodTime = 0.0;
    auto trials = std::size_t{0};  // what auto trials{0uz} makes, in C++17
    auto floodStart = steady_clock::now();

    std::cout << "CacheLineSize" << hint<decltype(CacheLineSize)>() << '\n';
    std::cout << "EvictCacheLineSize" << hint<decltype(EvictCacheLineSize)>() << '\n';
    std::cout << "Trials" << hint<decltype(Trials)>() << '\n';
    std::cout << "floodTime" << hint<decltype(floodTime)>() << '\n';
    std::cout << "trials" << hint<decltype(trials)>() << '\n';
    std::cout << "floodStart" << hint<decltype(floodStart)>() << '\n';
    std::cout << "size_t is unsigned long: " << std::boolalpha << std::is_same_v<std::size_t, unsigned long> << '\n';
    return 0;
}

