#include <chrono>
#include <cstdint>
#include <iostream>
#include <map>
#include <string>
#include <string_view>
#include <vector>

namespace desk::risk {  // C++17: the same as namespace desk { namespace risk {
using Qty = std::int64_t;  // C++11: another name for a type

struct Limits {
    Qty max_qty = 5'000;
    Limits() = default;                 // C++11: the constructor the compiler writes
    Limits(const Limits&) = delete;     // C++11: copying a Limits doesn't compile
};

[[nodiscard]] bool within(Qty qty, const Limits& limits) noexcept {  // C++17 attribute, C++11 noexcept
    return qty > 0 && qty <= limits.max_qty;
}
}  // namespace desk::risk

int g_orders = 0;
decltype(auto) orders() {  // C++14: (g_orders) names the variable, so this returns int&
    return (g_orders);
}

int main() {
    using namespace std::chrono_literals;
    using namespace std::string_literals;
    using namespace std::string_view_literals;

    const desk::risk::Limits limits{};
    std::vector sizes{300, 9'000, 0};  // C++17 CTAD: std::vector<int>
    for (desk::risk::Qty q : sizes) {
        if (desk::risk::within(q, limits)) ++orders();
    }
    std::cout << "accepted " << g_orders << " of " << sizes.size() << '\n';

    std::map<std::string, int> venues{{"XNAS", 1}, {"ARCX", 2}};
    if (auto it = venues.find("ARCX"); it != venues.end()) {  // C++17 if with an init-statement
        std::cout << it->first << " is venue " << it->second << '\n';
    }
    switch (const int id = venues.at("XNAS"); id) {  // C++17 switch with one
        case 1:
            std::cout << "XNAS is the primary\n";
            break;
        default:
            std::cout << "XNAS is venue " << id << '\n';
    }

    const auto timeout = 250ms;  // C++14: std::chrono::milliseconds
    const auto symbol = "AAPL"s;  // C++14: a std::string
    const auto view = "AAPL"sv;   // C++17: a std::string_view
    [[maybe_unused]] const int spare = 0;  // C++17: no warning when it's never used
    std::cout << timeout.count() << " ms, " << symbol.size() + view.size() << " chars\n";

    auto next_id = [id = 100]() mutable { return id++; };  // C++14 init-capture: a member named id
    auto twice = [](auto x) { return x + x; };             // C++14 generic lambda
    std::cout << next_id() << ' ' << next_id() << ' ' << twice(21) << ' ' << twice(1.25) << '\n';
    return 0;
}

