#include <chrono>
#include <cstdint>
#include <iostream>
#include <map>
#include <string>
#include <string_view>
#include <vector>

namespace feed::book {
using Px = std::int64_t;

[[nodiscard]] Px mid(Px bid, Px ask) noexcept {
    return bid + (ask - bid) / 2;
}
}  // namespace feed::book

int g_ticks = 0;
decltype(auto) ticks() {
    return (g_ticks);
}

int main() {
    using namespace std::chrono_literals;
    using namespace std::string_view_literals;

    std::vector bids{19270, 19271, 19275};
    std::vector asks{19272, 19275, 19276};
    for (std::size_t k = 0; k < bids.size(); ++k) {
        std::cout << "mid " << feed::book::mid(bids[k], asks[k]) << '\n';
        ++ticks();
    }
    std::cout << "ticks " << g_ticks << '\n';

    std::map<std::string, int> last_qty{{"AAPL", 300}, {"MSFT", 100}};
    if (auto it = last_qty.find("MSFT"); it != last_qty.end()) {
        std::cout << it->first << " last " << it->second << '\n';
    }

    auto next_seq = [seq = 1'000]() mutable { return seq++; };
    std::cout << "seq " << next_seq() << ' ' << next_seq() << ' ' << next_seq() << '\n';

    const auto window = 5s;
    const auto venue = "XNAS"sv;
    std::cout << std::chrono::duration_cast<std::chrono::milliseconds>(window).count() << " ms on " << venue << '\n';
    return 0;
}
